#!/usr/bin/env node
/**
 * Writes public/sounds/edu/not_yet.wav, the gentle "not yet" cue (OD-28, owner
 * review item L-02).
 *
 * The cue is synthesised here rather than generated by a paid audio model
 * (OD-23, zero spend): two soft marimba-like notes a whole tone apart, rising,
 * so a miss sounds like "try once more", never like a buzzer or a falling
 * "wrong" (B.26: a miss is not an error). Deterministic: the same bytes on every
 * run, so the committed file is reproducible and reviewable.
 *
 *   node scripts/generate-not-yet-sound.mjs
 */
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const RATE = 22_050;
const DURATION_S = 0.62;
const PEAK = 0.32; // about -10 dBFS; the player's own level (0.075) sits on top.

/** One soft mallet note: a sine with a quiet octave partial and an exponential decay. */
function note(t, start, freq, length) {
  const x = t - start;
  if (x < 0 || x > length) return 0;
  const attack = Math.min(1, x / 0.008); // an 8 ms attack: no click
  const decay = Math.exp(-x * 7.5);
  const tail = x > length - 0.03 ? (length - x) / 0.03 : 1; // fade to exact silence
  const tone = Math.sin(2 * Math.PI * freq * x) + 0.18 * Math.sin(2 * Math.PI * freq * 2 * x) + 0.05 * Math.sin(2 * Math.PI * freq * 3 * x);
  return tone * attack * decay * tail;
}

const samples = Math.round(RATE * DURATION_S);
const data = Buffer.alloc(samples * 2);
for (let i = 0; i < samples; i += 1) {
  const t = i / RATE;
  // C5 then D5, 140 ms apart.
  const value = 0.62 * note(t, 0, 523.25, 0.45) + 0.62 * note(t, 0.14, 587.33, DURATION_S - 0.14);
  data.writeInt16LE(Math.round(Math.max(-1, Math.min(1, value * PEAK)) * 32767), i * 2);
}

const header = Buffer.alloc(44);
header.write('RIFF', 0);
header.writeUInt32LE(36 + data.length, 4);
header.write('WAVE', 8);
header.write('fmt ', 12);
header.writeUInt32LE(16, 16);
header.writeUInt16LE(1, 20); // PCM
header.writeUInt16LE(1, 22); // mono
header.writeUInt32LE(RATE, 24);
header.writeUInt32LE(RATE * 2, 28);
header.writeUInt16LE(2, 32);
header.writeUInt16LE(16, 34);
header.write('data', 36);
header.writeUInt32LE(data.length, 40);

const out = resolve(dirname(fileURLToPath(import.meta.url)), '../public/sounds/edu/not_yet.wav');
writeFileSync(out, Buffer.concat([header, data]));
console.log(`wrote ${out} (${44 + data.length} bytes)`);
